<template><div class="page"><div class="page-header"><h2>话务台</h2></div><el-card shadow="never" style="margin-bottom:16px"><div class="search-bar"><div class="field"><label>客户电话</label><el-input v-model="searchPhone" placeholder="输入客户电话查询" size="small" style="width:220px" clearable @keyup.enter="doSearch"/></div><div class="field"><label>工单状态</label><el-select v-model="searchStatus" size="small" style="width:120px" clearable><el-option v-for="zt in ztOptions" :key="zt.code_cd" :label="zt.code_nm" :value="zt.code_cd"/></el-select></div><el-button type="primary" size="small" @click="doSearch" style="margin-left:auto">查询</el-button></div></el-card><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" @row-click="openDetail"><el-table-column prop="maintenance_id" label="工单号" width="110"/><el-table-column label="门店" width="90"><template #default="{row}">{{ row.store_cust_card || custCard(row.store_id) }}</template></el-table-column><el-table-column prop="short_description" label="故障描述" min-width="140" show-overflow-tooltip/><el-table-column label="优先级" width="70"><template #default="{row}">{{ row.priority||'-' }}</template></el-table-column><el-table-column label="状态" width="80" align="center"><template #default="{row}"><el-tag :type="statusTag(row.current_status)" size="small">{{ ztLabel(row.current_status) }}</el-tag></template></el-table-column><el-table-column prop="firstor" label="维修员" width="80"/><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button link type="primary" size="small" @click.stop="openDetail(row)">详情</el-button><el-button link type="success" size="small" @click.stop="openDispatch(row)" v-if="row.current_status==='1'">分派</el-button><el-button link type="warning" size="small" @click.stop="openClose(row)" v-if="row.current_status==='5'">关单</el-button></template></el-table-column></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="'工单详情 — '+(detail?.maintenance_id||'')" v-model="drawer" width="600px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="工单号">{{ detail.maintenance_id }}</el-descriptions-item><el-descriptions-item label="门店">{{ detail.store_cust_card || custCard(detail.store_id) }}</el-descriptions-item><el-descriptions-item label="故障简述" :span="2">{{ detail.short_description||'-' }}</el-descriptions-item><el-descriptions-item label="优先级">{{ detail.priority||'-' }}</el-descriptions-item><el-descriptions-item label="状态"><el-tag :type="statusTag(detail.current_status)" size="small">{{ ztLabel(detail.current_status) }}</el-tag></el-descriptions-item><el-descriptions-item label="维修员">{{ detail.firstor||'-' }}</el-descriptions-item><el-descriptions-item label="请求日期">{{ detail.request_time||'-' }}</el-descriptions-item><el-descriptions-item label="完成日期">{{ detail.close_time||'-' }}</el-descriptions-item></el-descriptions><div style="margin-top:16px;display:flex;gap:8px;justify-content:flex-end"><el-button type="primary" @click="openDispatch(detail)" v-if="detail.current_status==='1'">分派工单</el-button><el-button type="warning" @click="openClose(detail)" v-if="detail.current_status==='5'">确认关单</el-button></div></template></el-dialog><el-dialog title="分派工单" v-model="dispatchVisible" width="400px"><el-form :model="dispatchForm" label-width="80px"><el-form-item label="工单号"><el-input :model-value="dispatchForm.maintenance_id" disabled/></el-form-item><el-form-item label="分派部门"><el-select v-model="dispatchForm.group" style="width:100%"><el-option label="技术部" value="01"/><el-option label="实施部" value="02"/></el-select></el-form-item><el-form-item label="分派人"><el-input v-model="dispatchForm.engineer" placeholder="工程师ID"/></el-form-item><el-form-item label="备注"><el-input v-model="dispatchForm.remark" type="textarea" :rows="2"/></el-form-item></el-form><template #footer><el-button @click="dispatchVisible=false">取消</el-button><el-button type="primary" @click="doDispatch" :loading="dispatching">确认分派</el-button></template></el-dialog><el-dialog title="确认关单" v-model="closeVisible" width="400px"><el-form label-width="80px"><el-form-item label="工单号"><el-input :model-value="closeForm.maintenance_id" disabled/></el-form-item><el-form-item label="关单备注"><el-input v-model="closeForm.remark" type="textarea" :rows="3" placeholder="请输入关单原因"/></el-form-item></el-form><template #footer><el-button @click="closeVisible=false">取消</el-button><el-button type="primary" @click="doClose" :loading="closing">确认关单</el-button></template></el-dialog></div></template>
<script setup lang="ts">import {ref,reactive,onMounted} from 'vue';import {ElMessage} from 'element-plus';import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {useCustomerCards} from '@/composables/useCustomerCards';import {fetchMaintenanceDaily} from '@/api/itsm';import type {MntRecord} from '@/api/itsm';import request from '@/api/request';import {useDict} from '@/composables/useDict';import {fetchSyscodes} from '@/api/master'
const{items,loading,page,perPage,total,onSearch}=useListPage<MntRecord>(fetchMaintenanceDaily);const{drawer,detail,open}=useDetailDrawer<MntRecord>()
const{custCard}=useCustomerCards();const{dictLabel:ztLabel}=useDict('ZT')
const searchPhone=ref('');const searchStatus=ref('');const ztOptions=ref<{code_cd:string;code_nm:string}[]>([])
onMounted(async()=>{try{const r=await fetchSyscodes('ZT');ztOptions.value=r.data||[]}catch{}})
function statusTag(s:unknown){const m:Record<string,string>={'1':'info','2':'primary','3':'success','4':'warning','5':'primary','9':'danger'};return m[s as string]||'info'}
function doSearch(){const p:Record<string,string>={};if(searchPhone.value)p.phone=searchPhone.value;if(searchStatus.value)p.current_status=searchStatus.value;onSearch(p)}
function openDetail(row:MntRecord){open(row)}
const dispatchVisible=ref(false);const dispatchForm=reactive({maintenance_id:'',group:'01',engineer:'',remark:''});const dispatching=ref(false)
function openDispatch(row:MntRecord){dispatchForm.maintenance_id=row.maintenance_id||'';dispatchForm.group='01';dispatchForm.engineer='';dispatchForm.remark='';dispatchVisible.value=true}
async function doDispatch(){dispatching.value=true;try{await request.post(`/itsm/maintenance-daily/${dispatchForm.maintenance_id}/transition`,{to_status:'2',remark:dispatchForm.remark});ElMessage.success('分派成功');dispatchVisible.value=false;page.value=1;await doSearch()}catch{ElMessage.error('分派失败')}finally{dispatching.value=false}}
const closeVisible=ref(false);const closeForm=reactive({maintenance_id:'',remark:''});const closing=ref(false)
function openClose(row:MntRecord){closeForm.maintenance_id=row.maintenance_id||'';closeForm.remark='';closeVisible.value=true}
async function doClose(){closing.value=true;try{await request.post(`/itsm/maintenance-daily/${closeForm.maintenance_id}/transition`,{to_status:'3',remark:closeForm.remark});ElMessage.success('关单成功');closeVisible.value=false;page.value=1;await doSearch()}catch{ElMessage.error('关单失败')}finally{closing.value=false}}</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}.search-bar{display:flex;gap:12px;align-items:center}.field{display:flex;align-items:center;gap:6px}.field label{font-size:13px;color:#606266;white-space:nowrap}</style>
